ns.objectives["frFR"] = {
[2]="Apporter la griffe de Serres-tranchantes à Senani Thunderheart, au poste de Bois-brisé, en Ashenvale.",
[5]="Parler au chef Grual.",
[6]="Tuer Garrick Padfoot et rapporter sa tête à l'Adjoint Willem de l'Abbaye du Northshire.",
[7]="Tuer 10 Vermines kobold, puis revenir voir le maréchal McBride.",
[8]="Livrer une Lettre à Renée dans les Clairières de Tirisfal.",
[9]="Le Fermier Saldean veut que vous tuiez 20 Gardiens des moissons.",
[10]="Découvrir ce qu'est devenu le géomètre Scrimshank, et rapporter son équipement topographique au grand géomètre Fizzledowser à Gadgetzan.",
[11]="Apporter 8 Brassards peints de gnolls à l'Adjoint Rainer à la Caserne.",
[12]="Tuer 15 Trappeurs défias et 15 Contrebandiers défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.",
[13]="Tuer 15 Pilleurs défias et 15 Pillards défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.",
[14]="Tuer 15 Malandrins défias, 5 Eclaireurs défias et 5 Truands défias pour Gryan Stoutmantle, puis retourner le voir sur la Colline des sentinelles.",
[15]="Tuer 10 Ouvriers kobolds, puis revenir faire son rapport au maréchal McBride.",
[17]="Apporter 12 Champignons magenta à Ghak Healtouch à Thelsamar.",
[18]="Apporter 12 Masques rouges à l’Adjoint Willem à l’extérieur de l’Abbaye de Northshire.",
[19]="Rapporter la Tête de Tharil'zun au maréchal Marris, dans les Carmines.",
[20]="Rapporter 10 Haches détériorées au maréchal Marris de Lakeshire.",
[21]="Tuer 12 Travailleurs kobold, puis revenir voir le maréchal McBride, à l’Abbaye de Northshire.",
[22]="Salma Saldean a besoin de 8 Foies de Broche-tripes pour faire une Tourte au foie de Broche-tripes.",
[23]="Apporter la Patte d'Ursangous à Senani Thunderheart, au Poste de Bois-brisé, à Ashenvale.",
[24]="Apporter la Tête de Shadumbra à Senani Thunderheart, au Poste de Bois-brisé, dans Ashenvale.",
[25]="Tuer 12 Elémentaires d’eau corrompus au lac Mystral, à l’est de la Perce des Serres, et au sud-ouest du poste de Bois-brisé.\n\nFaire une reconnaissance sur le kiosque du lac Mystral ; celui qui a vue sur l’avant-poste de l’Alliance.\n\nRetourner voir Mastok Wrilehiss, au poste de Bois-brisé, dans Ashenvale.",
[26]="Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.",
[27]="Parler à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.",
[28]="Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.\n\nVous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve.",
[29]="Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l’apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.\n\nVous devez parler à Tajarri, au sanctuaire, afin de terminer l’épreuve.",
[30]="Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l’endroit où ces objets se trouvent.\n\nReformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.\n\nApporter le Pendentif reformé à Dendrite Starblaze, au village de Havrenuit, à Reflet-de-Lune.",
[31]="Retourner à Thunder Bluff et montrer le Pendentif du lion de mer à Turak Runetotem.",
[32]="Apporter le rapport à Zilzibin Drumlore à Orgrimmar.",
[33]="Apporter 8 pièces de Viande de loup coriace à Eagan Peltskinner, à l’extérieur de l’Abbaye de Northshire.",
[34]="Martie Jainrose de Lakeshire veut que vous tuiez Fouailleventre. Ramenez-lui ses défenses comme preuve.",
[35]="Le maréchal Dughan veut que vous parliez au garde Thomas.",
[36]="Verna Furlbrow veut que vous apportiez la Recette du ragoût de la marche de l'Ouest à Salma Saldean.",
[37]="Le garde Thomas veut que vous alliez vers le nord, le long de la rivière, à la recherche de deux gardes disparus, Rolf et Malakai.",
[38]="Salma Saldean veut 3 morceaux de Viande filandreuse de vautour, 3 Groins de Broche-tripes, 3 Yeux de murloc et 3 Okras.",
